/* NEXZO v132 — one-time consent, preference center, and on-demand permissions. */
(function(){
'use strict';
if(window.NEXZOConsent)return;
const KEY='nexzo:consent:v1',COOKIE='nexzo_consent_decided';
const read=()=>{
  try{const stored=JSON.parse(localStorage.getItem(KEY)||'null');if(stored&&stored.decided!==false)return stored}catch{}
  if(document.cookie.split(';').some(row=>row.trim().startsWith(`${COOKIE}=`)))return {necessary:true,analytics:false,personalization:false,decided:true,cookieFallback:true};
  return null;
};
function rememberDecision(){const secure=location.protocol==='https:'?'; Secure':'';document.cookie=`${COOKIE}=1; Max-Age=31536000; Path=/; SameSite=Lax${secure}`}
const write=value=>{const next={version:'2026-09-01',necessary:true,analytics:!!value.analytics,personalization:!!value.personalization,decided:true,updatedAt:new Date().toISOString()};try{localStorage.setItem(KEY,JSON.stringify(next))}catch{}rememberDecision();try{window.NEXZOSettings?.set?.({analytics:next.analytics,personalization:next.personalization})}catch{}window.dispatchEvent(new CustomEvent('nexzo:consent-changed',{detail:next}));return next};
function modal(manage=false){
  document.getElementById('nxConsentRoot')?.remove();const current=read()||{analytics:false,personalization:true};
  const root=document.createElement('div');root.id='nxConsentRoot';root.className=`nx-consent-backdrop${manage?' is-manage':''}`;
  root.innerHTML=`<section class="nx-consent" role="dialog" aria-modal="${manage?'true':'false'}" aria-labelledby="nxConsentTitle"><button type="button" class="nx-consent-close" aria-label="Close privacy preferences" ${manage?'':'hidden'}>×</button><div class="nx-consent-copy"><span class="nx-consent-shield">🛡</span><div><h2 id="nxConsentTitle">Your privacy, your choice</h2><p>Essential storage keeps sign-in and core features working. Optional analytics and personalization stay under your control. <a href="privacy.html">Privacy</a> · <a href="terms.html">Terms</a></p></div></div><div class="nx-consent-options" ${manage?'':'hidden'}><div class="nx-consent-option"><span><b>Necessary</b><small>Sign-in, security and essential preferences.</small></span><span class="nx-consent-badge">Always active</span></div><label class="nx-consent-option"><span><b>Analytics</b><small>Anonymous product analytics when configured.</small></span><input id="nxConsentAnalytics" type="checkbox" ${current.analytics?'checked':''}></label><label class="nx-consent-option"><span><b>Personalization</b><small>Use NEXZO activity to tailor learning.</small></span><input id="nxConsentPersonalization" type="checkbox" ${current.personalization?'checked':''}></label><p class="nx-permission-note">Camera, microphone and notifications are requested separately by your browser only when you use those features.</p></div><div class="nx-consent-actions"><button type="button" data-choice="reject">Only necessary</button><button type="button" data-choice="manage">Manage</button><button type="button" class="primary" data-choice="accept">Accept all</button><button type="button" class="primary" data-choice="save" ${manage?'':'hidden'}>Save choices</button></div></section>`;
  document.body.appendChild(root);const options=root.querySelector('.nx-consent-options'),save=root.querySelector('[data-choice=save]'),manageButton=root.querySelector('[data-choice=manage]');
  manageButton.onclick=()=>{root.classList.add('is-manage');options.hidden=false;save.hidden=false;manageButton.hidden=true;root.querySelector('.nx-consent-close').hidden=false;root.querySelector('.nx-consent').setAttribute('aria-modal','true')};
  root.querySelector('.nx-consent-close').onclick=()=>root.remove();root.querySelector('[data-choice=reject]').onclick=()=>{write({analytics:false,personalization:false});root.remove()};root.querySelector('[data-choice=accept]').onclick=()=>{write({analytics:true,personalization:true});root.remove()};save.onclick=()=>{write({analytics:root.querySelector('#nxConsentAnalytics').checked,personalization:root.querySelector('#nxConsentPersonalization').checked});root.remove()};root.addEventListener('click',event=>{if(manage&&event.target===root)root.remove()});
}
function initConsent(){if(!read())setTimeout(()=>modal(false),500)}
function initTilt(){/* Mouse parallax intentionally disabled for performance and accessibility. */}
async function enablePush(){if(!('Notification'in window))return {status:'unsupported'};if(!isSecureContext)return {status:'insecure'};const permission=await Notification.requestPermission();if(permission!=='granted')return {status:permission};if(!('serviceWorker'in navigator))return {status:'service-worker-unsupported'};const registration=await navigator.serviceWorker.register('./sw.js',{scope:'./'});const vapid=String(window.NEXZO_CONFIG?.WEB_PUSH_VAPID_KEY||'').trim();if(!vapid)return {status:'permission-granted',permission,registration,remotePush:'needs-vapid-key'};try{const app=await window.NEXZOFirebase.getApp(),m=await import(`https://www.gstatic.com/firebasejs/${window.NEXZOFirebase.version}/firebase-messaging.js`),messaging=m.getMessaging(app),token=await m.getToken(messaging,{vapidKey:vapid,serviceWorkerRegistration:registration});if(token){const c=await window.NEXZOFirebase.getContext({auth:true,firestore:true});if(c.auth.currentUser){await c.firestoreTools.setDoc(c.firestoreTools.doc(c.db,'users',c.auth.currentUser.uid,'settings','push'),{uid:c.auth.currentUser.uid,token,permission:'granted',platform:navigator.userAgent.slice(0,220),updatedAtMs:Date.now()},{merge:true})}return {status:'ready',token}}return {status:'no-token'}}catch(error){return {status:'error',error}}}
window.NEXZOConsent=Object.freeze({get:read,open:()=>modal(true),set:write,enablePush});
function boot(){initConsent();document.querySelectorAll('[data-nx-consent-manage]').forEach(button=>button.onclick=()=>modal(true))}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
